inputs = ['agbdyv', 'yd', 'gzavxk', 'exd', 'hzgz']
outputs = ['fdbdyv', 'yd', 'gzgvxk', 'exd', 'hzgz']

# Step 1: Find changed pairs
changed_pairs = []
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        changed_pairs.append((i, inp, out))

print("Changed pairs:", changed_pairs)

# Let's analyze each change
for idx, inp, out in changed_pairs:
    print(f"\nPair {idx}: '{inp}' -> '{out}'")
    # Show positions where they differ
    for i, (c1, c2) in enumerate(zip(inp, out)):
        if c1 != c2:
            print(f"  Position {i}: '{c1}' -> '{c2}'")
    # If lengths are different, show that too
    if len(inp) != len(out):
        print(f"  Length change: {len(inp)} -> {len(out)}")

